def fit(x, y, fn, init, bounds):
    from scipy.optimize import least_squares

    def err(p):
        a = fn(x, p)
        return (a @ ls(a, y) - y).ravel()
    r = least_squares(err, init, bounds=bounds, max_nfev=300)
    p = r.x
    a = fn(x, p)
    b = ls(a, y)
    e = a @ b - y
    h = np.sum(a * np.linalg.pinv(a).T, axis=1)
    return (np.sqrt(np.mean(e ** 2)), np.sqrt(np.mean((e / (1 - h[:, None])) ** 2)), p, lambda z: fn(z, p) @ b)

def _features(w, gain, interaction, kind):
    import itertools
    u = gain * w
    if kind == 'atan':
        z = np.arctan(u)
    elif kind == 'inv3':
        z = np.sinh(np.arcsinh(u) / 3)
    else:
        z = np.arcsinh(u)
    if not interaction:
        return np.column_stack((_aff(w), z))
    pairs = [z[:, i] * z[:, j] for (i, j) in itertools.combinations_with_replacement(range(w.shape[1]), 2)]
    return np.column_stack((_aff(w), z, *pairs))

def _predict(w, target, interaction, kind):
    from scipy.optimize import minimize_scalar
    n = len(target)
    scale = np.maximum(np.std(target, axis=0), 1e-08)

    def loss(gain):
        f = _features(w[:n], gain, interaction, kind)
        r = (f @ _ls(f, target) - target) / scale
        return np.mean(r * r)
    gain = minimize_scalar(loss, bounds=(0.8, 7), method='bounded').x
    f = _features(w, gain, interaction, kind)
    return f[n:] @ _ls(f[:n], target)
